(async()=>{const tbody=document.getElementById('rv-produtos');try{const d=await apiFetch('/operacoes/admin/relatorios/vendas');const eur=n=>Number(n||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'});document.getElementById('rv-encomendas').textContent=d.resumo.encomendas;document.getElementById('rv-receita').textContent=eur(d.resumo.receita_eur);document.getElementById('rv-ticket').textContent=eur(d.resumo.ticket_medio_eur);tbody.replaceChildren();for(const p of d.produtosMaisVendidos||[]){const tr=document.createElement('tr');for(const v of [p.nome_produto,p.unidades,eur(p.vendas_eur)]){const td=document.createElement('td');td.textContent=String(v??'');tr.append(td)}tbody.append(tr)}if(!tbody.children.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.textContent='Ainda não existem vendas pagas.';tr.append(td);tbody.append(tr)}}catch(e){tbody.replaceChildren();const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.textContent=e.message||'Erro ao carregar relatório de vendas.';tr.append(td);tbody.append(tr)}})();
